\[
\begin{split}
F\ n\text{-\uline{pseudo-cohérent}}
\quad\Longleftrightarrow\quad&
\Ho^i(F)\text{ \uline{cohérent pour} }i\geq n+1,\\
&\text{\uline{et} }\Ho^n(F)\text{ \uline{de type fini}.}
\end{split}
\]

\[
\begin{split}
F\ n\text{-\uline{pseudo-coherent}}
\quad\Longleftrightarrow\quad&
\Ho^i(F)\text{ \uline{coherent for} }i\geq n+1,\\
&\text{\uline{and} }\Ho^n(F)\text{ \uline{of finite type}.}
\end{split}
\]

